            TCXcontent += `        </Track>
      </Lap>
      <Notes>${utilities.htmlEncode(exportItem.description?exportItem.description:"") }</Notes>
      <Creator xsi:type="Device_t">
        <Name>--No GPS SELECTED--</Name>
        <UnitId>0</UnitId>
        <ProductID>0</ProductID>
        <Version>
          <VersionMajor>0</VersionMajor>
